import{z as r,x as i,o as t,c as s,q as A,j as l,D as n,d as e,s as o,S as m,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"期权到期事件","description":"","frontmatter":{"title":"期权到期事件","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ed-opex-event.md","filePath":"quant/ed-opex-event.md","lastUpdated":1791063341000}'),d={name:"quant/ed-opex-event.md"};function p(u,a,h,g,D,C){const B=i("Mermaid");return t(),s("div",null,[a[2]||(a[2]=A('<h1 id="期权到期事件" tabindex="-1">期权到期事件 <a class="header-anchor" href="#期权到期事件" aria-label="Permalink to &quot;期权到期事件&quot;">​</a></h1><div class="epigraph"><p>到期日，标的收盘价系统性地聚在大持仓行权价附近；这不是巧合，是两边的对冲流在同一价位上互相抵消。</p><footer>—— 据 Ni, Pearson, Poteshman and Whitefoot, Journal of Financial Economics, 2005；Stoll and Whaley, Financial Analysts Journal, 1987 整理</footer></div><p><a href="/quant/ed-index-rebalance-event">上一课</a>的流量来自跟踪规则的会计；本课的流量来自衍生品的对冲会计。期权到期是日历上最精确的事件：时点定到收盘，规模可由未平仓合约与行权价分布事先近似。本课写到期日历、对冲流的方向与集中、行权价聚集（pin）与到期后的回吐；波动率交易面另见<a href="/quant/vt-event-vol">事件波动</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>到期事件的特殊性在于：<strong>载荷可由公开持仓算出</strong>。财报的载荷无人预知，指数调整的由规则给出，期权的载荷藏在每天公布的未平仓量里。做市商对客户的净头寸决定到期前的对冲流方向：客户买期权，做市商持正 gamma，逆势对冲起稳定作用；客户卖期权，做市商持负 gamma，顺势对冲起放大作用。把全行权价的净 gamma 加总，</p><p><span class="marginnote">术语翻译：gamma 就是「标的每动 1 元，对冲仓位要跟着改多少」的敏感度。正 gamma 意味着涨了要卖一点、跌了要买一点，动作天然逆势、像踩刹车；负 gamma 正相反，涨了追买、跌了追卖，天然像踩油门。</span></p> \\[\\Gamma_{\\mathrm{tot}}=\\sum_K \\mathrm{OI}_K\\cdot \\Gamma_K(S,t), \\]<p>其符号与集中度就是尾盘流量形状的估计。缺口有三：第一，把到期效应当成「庄家操纵价位」的民间叙事（max pain），丢掉对冲会计的真实机制；第二，忽略时点结构——对冲流在到期前一周累积、最后一日尾盘最尖；第三，把个股期权、指数期权与期货的到期混成一个「到期日」，而交割机制与流量并不同步。</p><h3 id="pin-的条件" tabindex="-1">Pin 的条件 <a class="header-anchor" href="#pin-的条件" aria-label="Permalink to &quot;Pin 的条件&quot;">​</a></h3><p>聚集不是常态而是条件事件。当某行权价 \\(K^\\*\\) 的未平仓高度集中、现价满足 \\(|S-K^\\*|\\) 足够小、距到期足够短时，gamma 急剧变尖：价格每偏离一档，做市商需买卖的标的量超线性增长，对冲流把价格推回 \\(K^\\*\\)，尾盘方差被压扁。反过来，负 gamma 集中时同样的机制把价格推离。同一个日历事件，两种相反的尾部——先测剖面符号，再谈交易。</p><p><span class="marginnote">Ni、Pearson、Poteshman 与 Whitefoot（2005）：到期日收盘价聚集在大持仓行权价的频率显著高于普通日，且随该行权价的未平仓集中度增强——可检验的对冲后果，不是操纵传闻。</span></p>',11)),(t(),l(m,null,{default:n(()=>[o(B,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E4%BB%8A%E5%A4%A9%E5%B0%BE%E7%9B%98%E6%98%AF%20pin%20%E8%BF%98%E6%98%AF%E6%9A%B4%E8%B5%B0%3F%22%5D%20--%3E%20C1%7B%22K*%20%E9%99%84%E8%BF%91%E6%9C%AA%E5%B9%B3%E4%BB%93%E9%AB%98%E5%BA%A6%E9%9B%86%E4%B8%AD%3F%22%7D%0A%20%20C1%20--%20%22%E5%90%A6%22%20--%3E%20QUIET%5B%22%E6%97%A0%E5%BC%BA%E5%AF%B9%E5%86%B2%E6%B5%81%3A%20%E6%8C%89%E5%B8%B8%E6%80%81%E6%B3%A2%E5%8A%A8%E5%A4%84%E7%90%86%22%5D%0A%20%20C1%20--%20%22%E6%98%AF%22%20--%3E%20C2%7B%22%E5%87%80%20gamma%20%E7%AC%A6%E5%8F%B7%3F%22%7D%0A%20%20C2%20--%20%22%E6%AD%A3%20gamma%20%E9%9B%86%E4%B8%AD%22%20--%3E%20PIN%5B%22%E5%AF%B9%E5%86%B2%E6%B5%81%E6%8A%8A%E4%BB%B7%E6%A0%BC%E5%8E%8B%E5%9B%9E%20K*%3A%20%E5%B0%BE%E7%9B%98%E6%96%B9%E5%B7%AE%E8%A2%AB%E5%8E%8B%E6%89%81%22%5D%0A%20%20C2%20--%20%22%E8%B4%9F%20gamma%20%E9%9B%86%E4%B8%AD%22%20--%3E%20BLAST%5B%22%E5%AF%B9%E5%86%B2%E6%B5%81%E9%A1%BA%E5%8A%BF%E6%94%BE%E5%A4%A7%3A%20%E4%BB%B7%E6%A0%BC%E8%A2%AB%E6%8E%A8%E7%A6%BB%20%E6%96%B9%E5%B7%AE%E6%94%BE%E5%A4%A7%22%5D%0A%20%20PIN%20--%3E%20ACT%5B%22%E5%85%88%E6%B5%8B%E5%89%96%E9%9D%A2%E7%AC%A6%E5%8F%B7%20%E5%86%8D%E9%80%89%E7%AD%96%E7%95%A5%22%5D%0A%20%20BLAST%20--%3E%20ACT%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"方法",tabindex:"-1"},[e("方法 "),E("a",{class:"header-anchor",href:"#方法","aria-label":'Permalink to "方法"'},"​")],-1)),a[4]||(a[4]=E("p",null,[E("strong",null,"日历分层。"),e(" 月度与季度到期（含叠加指数期权与期货的多重到期日）、个股实物交割与指数现金交割分列；期货滚动的移仓期是另一段流量，不与期权到期混账。多重到期日的叠加成交量造就了著名的到期巨量，也促成了后来的收盘程序改革。")],-1)),a[5]||(a[5]=E("p",null,[E("strong",null,"持仓剖面换流量。"),e(" 每日收盘后取 OI 与行权价分布，逐档算 \\(\\Gamma_K\\) 与净符号，得尾盘对冲流的估计剖面。不这么做会错在哪：只看总 OI 或最大仓位行权价，分不清稳定与放大两种尾部，把「有时 pin、有时暴走」当成随机噪声。")],-1)),a[6]||(a[6]=E("p",null,[E("strong",null,"窗口三段。"),e(" 到期前一周（对冲流渐强、波动特征改变）、到期日尾盘（gamma 最尖）、次日（回吐，方差回归常态）。把到期日的异常当新体制，会错把一日现象外推成永久参数。")],-1)),(t(),l(m,null,{default:n(()=>[o(B,{id:"mermaid-42",class:"mermaid",graph:"flowchart%20TD%0A%20%20CAL%5B%22%E5%88%B0%E6%9C%9F%E6%97%A5%E5%8E%86%EF%BC%9A%E5%A4%9A%E9%87%8D%E5%88%B0%E6%9C%9F%22%5D%20--%3E%20OI%5B%22OI%20%E4%B8%8E%E8%A1%8C%E6%9D%83%E4%BB%B7%E5%88%86%E5%B8%83%E5%BF%AB%E7%85%A7%22%5D%0A%20%20OI%20--%3E%20GAMMA%5B%22%E5%87%80%20gamma%20%E5%89%96%E9%9D%A2%EF%BC%9A%E7%AC%A6%E5%8F%B7%E4%B8%8E%E9%9B%86%E4%B8%AD%E5%BA%A6%22%5D%0A%20%20GAMMA%20--%3E%20POS%5B%22%E6%AD%A3%20gamma%EF%BC%9A%E9%80%86%E5%8A%BF%E5%AF%B9%E5%86%B2%20%E4%BB%B7%E6%A0%BC%E8%A2%AB%E5%8E%8B%E5%90%91%E8%A1%8C%E6%9D%83%E4%BB%B7%22%5D%0A%20%20GAMMA%20--%3E%20NEG%5B%22%E8%B4%9F%20gamma%EF%BC%9A%E9%A1%BA%E5%8A%BF%E5%AF%B9%E5%86%B2%20%E6%96%B9%E5%B7%AE%E6%94%BE%E5%A4%A7%22%5D%0A%20%20POS%20--%3E%20NEXT%5B%22%E6%AC%A1%E6%97%A5%E5%9B%9E%E5%90%90%EF%BC%9A%E4%BD%93%E5%88%B6%E5%9B%9E%E5%BD%92%22%5D%0A%20%20NEG%20--%3E%20NEXT%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=A('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>经济机制是<strong>对冲需求的时限性</strong>。期权临近到期，时间价值归零，对冲比率的敏感度集中到行权价附近；同一时刻，所有参与者共享同一条日历。对冲流因此不是噪声：它是可预测的方向、可估计的规模、有明确截止时间的需求——这正是五元组的定义。价格聚集是对冲流在行权价上的驻点；尾盘的成交量是持仓向交割机制交接的记账。到期后的回吐来自时限消失：gamma 剖面重新展开，方差回到由标的自身波动决定的水平。</p><p><span class="marginnote">数字实例：一份 delta 0.50 的平值期权，到期前一周 gamma 约 0.05——标的涨 1 元，delta 升到约 0.55，做市商要多买 0.05 份标的保持中性。到期当天价格贴着行权价时，同样的 1 元移动会让 delta 在 0 与 1 之间近乎跳变，对冲动作被放大数倍，这就是尾盘流量「最尖」的来源。</span></p><p>客户行为侧把链条补全：期权市场的净需求改变期权价格与做市商的对冲需求（Gârleanu、Pedersen 与 Poteshman，2009；净买压见 Bollen 与 Whaley，2004），对冲需求再反馈到标的价格——到期日只是反馈被时限放大的日子。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>Pin 是条件事件，不是保证；把「大 OI 行权价必被钉住」当交易依据，会在负 gamma 集中的月份反复吃亏。交割机制因市场而异：现金交割把流量压在收盘，实物交割摊到行权日前后，跨市场套用模板要重校准。0DTE 让到期窗口变密变短，日内出现多个「准到期时点」，微观形状见<a href="/quant/amaya-0dte-volatility">0DTE 与波动</a>；推断协议用<a href="/quant/obd-eventstudy-micro">事件研究的微观版本</a>。未平仓数据是收盘快照，日内建仓不进剖面，尾盘突发大单会改变对冲流方向——剖面是估计，不是承诺。</p><p><span class="marginnote">常见误区：「最大持仓行权价必被 pin」。pin 要先看该价位附近净 gamma 的符号——负 gamma 集中时同样的到期日会把价格推离而不是钉住；只看 OI 大小不看符号，会在这些月份反复吃亏。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>到期是载荷可由公开持仓算出的事件：净 gamma 剖面给出尾盘对冲流的方向与集中度。</li><li>正 gamma 稳定、负 gamma 放大；行权价聚集（pin）是条件事件，不是常态保证。</li><li>窗口三段：到期前一周、到期日尾盘、次日回吐；回吐账不能省。</li><li>多重到期与期货滚动不同步，分账处理；交割机制决定流量压在哪个时段。</li><li>出处：Stoll and Whaley, <em>Financial Analysts Journal</em>, 1987；Ni, Pearson, Poteshman and Whitefoot, <em>Journal of Financial Economics</em>, 2005；Gârleanu, Pedersen and Poteshman, <em>Journal of Finance</em>, 2009。</li></ul>',9))])}const c=r(d,[["render",p]]);export{f as __pageData,c as default};
